//Water Slash Lightning
//Primary shape based variation + Distortion.

//based on https://www.youtube.com/shorts/qqgNswdCTqQ

#define MOD3 vec3(.1031,.11369,.13787)

vec3 hash33(vec3 p3)
{
	p3 = fract(p3 * MOD3);
    p3 += dot(p3, p3.yxz+19.19);
    return -1.0 + 2.0 * fract(vec3((p3.x + p3.y)*p3.z, (p3.x+p3.z)*p3.y, (p3.y+p3.z)*p3.x));
}

float simplex_noise(vec3 p)
{
    const float K1 = 0.333333333;
    const float K2 = 0.166666667;

    vec3 i = floor(p + (p.x + p.y + p.z) * K1);
    vec3 d0 = p - (i - (i.x + i.y + i.z) * K2);

    // thx nikita: https://www.shadertoy.com/view/XsX3zB
    vec3 e = step(vec3(0.0), d0 - d0.yzx);
	vec3 i1 = e * (1.0 - e.zxy);
	vec3 i2 = 1.0 - e.zxy * (1.0 - e);

    vec3 d1 = d0 - (i1 - 1.0 * K2);
    vec3 d2 = d0 - (i2 - 2.0 * K2);
    vec3 d3 = d0 - (1.0 - 3.0 * K2);

    vec4 h = max(0.6 - vec4(dot(d0, d0), dot(d1, d1), dot(d2, d2), dot(d3, d3)), 0.0);
    vec4 n = h * h * h * h * vec4(dot(d0, hash33(i)), dot(d1, hash33(i + i1)), dot(d2, hash33(i + i2)), dot(d3, hash33(i + 1.0)));

    return dot(vec4(31.316), n);
}

vec2 noise( in vec3 x )
{
    return vec2( simplex_noise(x), simplex_noise(x+vec3(1.0)) );
}

float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

float sdCircle( vec2 p, float r )
{
    return length(p) - r;
}

float opSmoothSubtraction( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2+d1)/k, 0.0, 1.0 );
    return mix( d2, -d1, h ) + k*h*(1.0-h);
}

vec2 hash21(float p)
{
    vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx+p3.yz)*p3.zy);

}

float erode(float d, float size, vec2 p){
  for(float i=1.; i<5.; i++){
    vec2 s = vec2(size, size);
    vec2 q = p+hash21(i)*size*10.;
    //q.x -= iTime*0.15;
    q = q - s*round(q/s);

    float d2 = sdCircle(q, size*0.2);//
    d = opSmoothSubtraction(d2, d, 0.02);
  }
  return d;
}

float waveFunc(float x){
  return sin(x*5.-iTime)*0.1 + sin(x*15.-iTime)*0.01;
}

float opIntersection( float d1, float d2 )
{
    return max(d1,d2);
}

float seed = 0.;
vec3 map(vec2 p, float w)
{
  p += noise(vec3(p*0.5, iTime*0.2+seed)).xy*0.4;
  p += noise(vec3(p, iTime*0.2+seed)).xy*0.2;
  p += noise(vec3(p*5., iTime*0.2+seed)).xy*0.05;
  vec2 uv = p*vec2(1., 1./w);
  uv.x = mod(uv.x+iTime*3.+seed*0.5, 4.);
  uv.x -= 0.5;
  float d = sdCircle(uv, 0.5);

  return vec3(p,d);
}


